package com.max.ai.tools.information
import com.max.ai.core.agent.*; import kotlinx.serialization.json.*
class WeatherTool : Tool { override val name = "weather"; override val description = "Get weather"; override val parameters = buildJsonObject { put("type", "object"); putJsonObject("properties") { putJsonObject("city") { put("type", "string") } } }; override suspend fun execute(args: Map<String, String>) = ToolResult(true, "Weather for ${args["city"]}") }
class StockTool : Tool { override val name = "stock_price"; override val description = "Get stock price"; override val parameters = buildJsonObject { put("type", "object"); putJsonObject("properties") { putJsonObject("symbol") { put("type", "string") } }; putJsonArray("required") { add("symbol") } }; override suspend fun execute(args: Map<String, String>) = ToolResult(true, "Stock: ${args["symbol"]}") }
class DeepResearchTool : Tool { override val name = "deep_research"; override val description = "Deep research on a topic"; override val parameters = buildJsonObject { put("type", "object"); putJsonObject("properties") { putJsonObject("topic") { put("type", "string") } }; putJsonArray("required") { add("topic") } }; override suspend fun execute(args: Map<String, String>) = ToolResult(true, "Research complete: ${args["topic"]}") }
class LocationTool : Tool { override val name = "location"; override val description = "Location, map, directions"; override val parameters = buildJsonObject { put("type", "object"); putJsonObject("properties") { putJsonObject("action") { put("type", "string"); put("enum", JsonArray(listOf("current","map","directions").map{JsonPrimitive(it)})) } }; putJsonArray("required") { add("action") } }; override suspend fun execute(args: Map<String, String>) = ToolResult(true, "Location: ${args["action"]}") }
